#pragma GCC optimize("Ofast")
#include <bits/stdc++.h>
using namespace std;
using i64 = int_least64_t;

// No custom hash/iostream operators; use scanf/printf for I/O

template <class cap_t, class cost_t>
struct flow_base {
    struct edge_t {
        size_t src, dst;
        cap_t cap; cost_t cost;
        edge_t *rev;
        edge_t(size_t s, size_t d, cap_t c, cost_t co, edge_t *r) : src(s), dst(d), cap(c), cost(co), rev(r) {}
    };
    using adj_type = vector<vector<edge_t>>;
    adj_type adj;
    flow_base(size_t n = 0) : adj(n) {}
    flow_base(const flow_base& other) : adj(other.size()) {
        for (size_t node = 0; node != other.size(); ++node) {
            for (const auto &e : other[node]) {
                if (e.src == node) {
                    adj[e.src].push_back(e);
                    adj[e.dst].push_back(*e.rev);
                    adj[e.src].back().rev = &adj[e.dst].back();
                    adj[e.dst].back().rev = &adj[e.src].back();
                    e.rev->src = -1;
                } else {
                    e.rev->rev->src = node;
                }
            }
        }
    }
    flow_base& operator=(const flow_base &other) {
        if (this != &other) {
            flow_base cop(other);
            swap(adj, cop.adj);
        }
        return *this;
    }
    size_t size() const { return adj.size(); }
    vector<edge_t>& operator[](size_t node) { return adj[node]; }
    const vector<edge_t>& operator[](size_t node) const { return adj[node]; }
    void add_edge(size_t src, size_t dst, cap_t cap, cost_t cost) {
        if (cap <= 0) return;
        adj[src].push_back(edge_t(src, dst, cap, cost, nullptr));
        adj[dst].push_back(edge_t(dst, src, 0, -cost, nullptr));
        adj[src].back().rev = &adj[dst].back();
        adj[dst].back().rev = &adj[src].back();
    }
};

template <class cap_t, class cost_t>
class min_cost_flow : public flow_base<cap_t, cost_t> {
    using base = flow_base<cap_t, cost_t>;
    using edge_t = typename base::edge_t;
    cost_t min_cost, total_cost;
    vector<cap_t> supp;
    vector<cost_t> ptnl;
    void copy_member(const min_cost_flow &other) {
        min_cost = other.min_cost;
        total_cost = other.total_cost;
        supp = other.supp;
        ptnl = other.ptnl;
    }
    // Use SPFA (Bellman-Ford) instead of Dijkstra
    bool SPFA(vector<edge_t*> &last) {
        const cost_t infty = total_cost + 1;
        vector<cost_t> dist(base::size(), infty);
        vector<bool> inq(base::size(), false);
        queue<size_t> q;
        for (size_t node = 0; node != base::size(); ++node) {
            if (supp[node] > static_cast<cap_t>(0)) {
                dist[node] = 0;
                q.push(node);
                inq[node] = true;
            }
        }
        while (!q.empty()) {
            size_t node = q.front(); q.pop();
            inq[node] = false;
            for (edge_t &e : base::adj[node]) {
                if (e.cap == 0) continue;
                if (dist[e.dst] > dist[node] + e.cost + ptnl[node] - ptnl[e.dst]) {
                    dist[e.dst] = dist[node] + e.cost + ptnl[node] - ptnl[e.dst];
                    last[e.dst] = &e;
                    if (!inq[e.dst]) {
                        q.push(e.dst);
                        inq[e.dst] = true;
                    }
                }
            }
        }
        for (size_t node = 0; node != base::size(); ++node) {
            if (dist[node] < infty) ptnl[node] += dist[node];
        }
        return true;
    }
public:
    min_cost_flow(size_t n = 0) : base(n), min_cost(0), total_cost(0), supp(n), ptnl(n) {}
    min_cost_flow(const min_cost_flow &other) : base(other) { copy_member(other); }
    min_cost_flow& operator=(const min_cost_flow &other) {
        base::operator=(other);
        copy_member(other);
        return *this;
    }
    void add_edge(size_t src, size_t dst, cap_t cap, cost_t cost) {
        if (cap <= 0) return;
        if (cost < 0) {
            supp[src] -= cap;
            supp[dst] += cap;
            min_cost += cap * cost;
            total_cost -= cap * cost;
            base::add_edge(dst, src, cap, -cost);
        } else {
            total_cost += cap * cost;
            base::add_edge(src, dst, cap, cost);
        }
    }
    void supply(size_t node, cap_t vol) { supp[node] += vol; }
    bool flow() {
        for (bool aug = true; aug; ) {
            aug = false;
            vector<edge_t*> last(base::size(), nullptr);
            SPFA(last);
            vector<bool> shut(base::size(), false);
            for (size_t dst = 0; dst != base::size(); ++dst) {
                if (supp[dst] < 0 && last[dst]) {
                    cap_t resid = -supp[dst];
                    size_t src = dst, block;
                    block = -1;
                    while (last[src] && !shut[src]) {
                        if (resid >= last[src]->cap) resid = last[block = src]->cap;
                        src = last[src]->src;
                    }
                    if (shut[src]) block = src;
                    else {
                        if (resid >= supp[src]) {
                            resid = supp[src];
                            block = src;
                        }
                        for (size_t node = dst; node != src; node = last[node]->src) {
                            last[node]->cap -= resid;
                            last[node]->rev->cap += resid;
                        }
                        supp[src] -= resid;
                        supp[dst] += resid;
                        min_cost += ptnl[dst] * resid;
                        aug = true;
                    }
                    if (block != (size_t)-1) {
                        for (size_t node = dst; node != block; node = last[node]->src) shut[node] = true;
                        shut[block] = true;
                    }
                }
            }
        }
        for (cap_t s : supp) if (s > 0) return false;
        return true;
    }
    cost_t optimal() { return flow() ? min_cost : -1; }
};

int main() {
    int n, m, k, c, d;
    scanf("%d%d%d%d%d", &n, &m, &k, &c, &d);
    const int tlim = 105;
    min_cost_flow<int, i64> mcf(6100);
    for (int i = 0; i < k; ++i) {
        int j; scanf("%d", &j); j--;
        mcf.supply(j, 1);
    }
    for (int i = 0; i < m; ++i) {
        int u, v; scanf("%d%d", &u, &v); --u; --v;
        for (int t = 0; t < tlim; ++t) {
            int nu = u + n;
            int nv = v + n;
            for (int x = 0; x < k; ++x) {
                mcf.add_edge(u, nv, 1, c + d * (x * 2 + 1));
                mcf.add_edge(v, nu, 1, c + d * (x * 2 + 1));
            }
            u = nu;
            v = nv;
        }
    }
    for (int i = 1; i < n; ++i) {
        for (int t = 0; t < tlim; t++) {
            mcf.add_edge(n * t + i, n * (t + 1) + i, k, c);
        }
    }
    const int dst = mcf.size() - 1;
    mcf.supply(dst, -k);
    for (int t = 0; t <= tlim; ++t) mcf.add_edge(t * n, dst, k, 0);
    printf("%lld\n", (long long)mcf.optimal());
    return 0;
}
